from lib import *
S = SS('s15')
steps = [
    step("单域名 48 个请求、服务器每个延迟 0.3 s、全局并发 100,只改 CONCURRENT_REQUESTS_PER_DOMAIN = 1、2、4、8、16。默认的 asyncio reactor 下,服务器端看到的同时处理峰值永远是 48,总耗时都是 0.35~0.38 s——每域名限制没有生效;改用 SelectReactor,峰值严格等于设置值 1、2、4、8、16,总耗时 14.69、7.35、3.70、1.88、0.96 s,贴着理想值 48×0.3/N;TWISTED_REACTOR_ENABLED=False(无 reactor)也生效(14.65、7.35、3.68、1.85、0.95 s)。", t=tl(S(1)), mark=lidx(S(1), '           1 ', '           4 ', '          16 '), done=lidx(S(1), '每域名并发'), b=bars([['asyncio 默认 N=1', 0.35, '0.35 s(峰值 48)'], ['SelectReactor N=1', 14.69, '14.69 s(峰值 1)'], ['asyncio 默认 N=8', 0.36, '0.36 s(峰值 48)'], ['SelectReactor N=8', 1.88, '1.88 s(峰值 8)']], 14.69, mark=[0, 2], done=[1, 3]), kv=KV([['asyncio reactor(默认)', '峰值 48,限制没生效'], ['SelectReactor', '峰值 = N,生效'], ['无 reactor', '峰值 = N,生效'], ['这是 2.19.0 本机实测', '其它版本没验证']], ['asyncio reactor(默认)'])),
    step("原因:每个下载槽有 concurrency(这里 4)和 transferring(正在传输的请求集合);放行靠 free_transfer_slots() = concurrency − len(transferring)。给 Downloader._download 打补丁记录每次开始下载时槽里的 transferring 数:asyncio reactor 下是 1, 1, 2, 3, 4, 5, … 一路涨到 16(服务器峰值 16);SelectReactor 下涨到 4 就停在 4(1, 1, 2, 3, 4, 4, 4 …,服务器峰值 4)。asyncio 下请求是用 create_task 排的队,transferring 要等任务真正跑起来才增加,放行循环看不到这个数在涨,于是把队列里的请求一次放光。", t=tl(S(2)), mark=lidx(S(2), 'asyncio reactor(默认)'), done=lidx(S(2), 'SelectReactor'), kv=KV([['槽的 concurrency', '4'], ['asyncio 下 transferring', '1,2,3,…,16(超过 4)'], ['SelectReactor 下', '最多 4'], ['机制', 'create_task 延迟了 transferring 的增加']], ['asyncio 下 transferring'])),
    step("全局 CONCURRENT_REQUESTS 在引擎层面按“在途请求数”判断(needs_backout),asyncio reactor 下照样有效:两个主机名各 16 个请求、每域名并发 100,全局 4 → 服务器总峰值 4(每个主机 2),耗时 2.46 s;全局 6 → 6(各 3),1.87 s;全局 16 → 16(各 8),0.65 s。所以 asyncio 下想限制并发,要靠全局限制。", t=tl(S(3)), mark=lidx(S(3), '           4 ', '           6 '), done=lidx(S(3), '          16 '), b=bars([['全局 4', 2.46, '2.46 s(峰值 4)'], ['全局 6', 1.87, '1.87 s(峰值 6)'], ['全局 16', 0.65, '0.65 s(峰值 16)']], 2.46, mark=[0], done=[1, 2]), kv=KV([['全局 4', '总峰值 4(各主机 2)'], ['全局 6', '总峰值 6(各 3)'], ['全局 16', '总峰值 16(各 8)']], ['全局 4'])),
    step("DOWNLOAD_DELAY 走另一条路径:有延迟时每次只放出一个请求,下一个等 delay 之后再放(_process_queue 里 if delay 分支),在 asyncio reactor 下也生效。单域名 24 个请求、服务器延迟 0.3 s、每域名并发 8:DOWNLOAD_DELAY = 0 时峰值 24、总耗时 0.34 s;= 0.1 时峰值 4、2.73 s,相邻请求到达间隔的中位数 101 ms;= 0.2 时峰值 2、5.13 s,间隔 201 ms。峰值 ≈ 请求耗时 ÷ 间隔(0.3/0.1 ≈ 3~4)。", t=tl(S(4)), mark=lidx(S(4), '               0.1', '               0.2'), done=lidx(S(4), '                 0 '), b=bars([['DELAY=0', 0.34, '0.34 s(峰值 24)'], ['DELAY=0.1', 2.73, '2.73 s(峰值 4)'], ['DELAY=0.2', 5.13, '5.13 s(峰值 2)']], 5.13, mark=[1, 2], done=[0]), kv=KV([['DOWNLOAD_DELAY=0', '峰值 24'], ['= 0.1', '峰值 4,到达间隔 101 ms'], ['= 0.2', '峰值 2,到达间隔 201 ms']], ['= 0.1'])),
    step("CONCURRENT_REQUESTS_PER_IP(换成 ScrapyPriorityQueue)和 DOWNLOAD_SLOTS 里某个域名的 concurrency 走的是同一条放行路径,现象相同:限制设成 3,asyncio reactor 下服务器峰值 48,SelectReactor 下峰值 3;无 reactor 模式下这两个也是 48,没有被限制——因为那里生效的每域名限制来自 aiohttp 自己的连接器,只认 CONCURRENT_REQUESTS_PER_DOMAIN。", t=tl(S(5)), mark=lidx(S(5), 'PER_IP=3', 'DOWNLOAD_SLOTS'), kv=KV([['asyncio reactor', 'PER_IP / DOWNLOAD_SLOTS 峰值 48'], ['SelectReactor', '峰值 3(生效)'], ['无 reactor', '峰值 48:aiohttp 只认 PER_DOMAIN']], ['asyncio reactor'])),
    step("无 reactor 模式下每域名限制生效的原因,在 aiohttp 下载处理器的源码里:aiohttp.TCPConnector(limit=self._pool_size_total, limit_per_host=self._pool_size_per_host)——连接池大小来自 CONCURRENT_REQUESTS 和 CONCURRENT_REQUESTS_PER_DOMAIN,是硬上限(源码注释:hard limit on simultaneous connections per host)。所以同样的设置在三种运行方式下表现不一样,这是 2.19.0 本机实测的结果。", t=tl(S(6)), mark=lidx(S(6), 'limit_per_host', 'limit='), done=lidx(S(6), 'TCPConnector'), kv=KV([['limit', 'aiohttp 连接器:= CONCURRENT_REQUESTS'], ['limit_per_host', '= CONCURRENT_REQUESTS_PER_DOMAIN'], ['含义', '硬上限,独立于下载槽']], ['limit_per_host'])),
]
A = mkarts('s15', 15, 'Scrapy,并发,CONCURRENT_REQUESTS,每域名限制,下载槽,asyncio,真实验证,动画演示',
    '在 Scrapy 2.19.0 本机实测并发限制:默认 asyncio reactor 下 CONCURRENT_REQUESTS_PER_DOMAIN 没有生效(单域名 48 个请求峰值始终 48,SelectReactor 下峰值等于设置值);全局 CONCURRENT_REQUESTS 和 DOWNLOAD_DELAY 有效;PER_IP 和 DOWNLOAD_SLOTS 同样失效;无 reactor 模式的限制来自 aiohttp 连接器。',
    '文档说 CONCURRENT_REQUESTS_PER_DOMAIN 限制单个域名的并发。这篇在服务器端数同时在处理的请求,发现默认的 asyncio reactor 下它根本拦不住一次性涌入的请求;全局限制和 DOWNLOAD_DELAY 才是靠得住的。本文的结论都是 2.19.0 本机实测。',
    [('48', '默认 asyncio reactor 下,CONCURRENT_REQUESTS_PER_DOMAIN=1~16 时单域名的服务器端峰值(SelectReactor 下等于设置值)'), ('1 → 16', '放行循环里槽的 transferring 数一路涨到 16,而 concurrency 只有 4'), ('4 / 2', 'DOWNLOAD_DELAY 为 0.1、0.2 时的服务器峰值(有效的限制手段)')],
    [('预期与实测', '<p>文档上,每个域名(下载槽)同时下载的请求数不超过 <code>CONCURRENT_REQUESTS_PER_DOMAIN</code>。实测 2.19.0 在 SelectReactor 和无 reactor 模式下确实如此,但默认的 asyncio reactor 下单域名的并发等于已经排在槽里的请求数,与设置无关。</p>'),
     ('机制', '<p>槽按 <code>concurrency − len(transferring)</code> 放行,而 asyncio 下下载是以任务的方式排队的,<code>transferring</code> 要等任务运行才增加,放行循环看不到,于是一次放光。</p>'),
     ('哪些限制有效', '<p>全局 <code>CONCURRENT_REQUESTS</code>(引擎按在途请求数判断)和 <code>DOWNLOAD_DELAY</code>(每次只放出一个)在 asyncio reactor 下有效。</p>'),
     ('延迟的效果', '<p>有 <code>DOWNLOAD_DELAY</code> 时相邻请求间隔等于延迟,同时在途的请求数约等于请求耗时除以延迟。</p>'),
     ('PER_IP 与 DOWNLOAD_SLOTS', '<p>它们设置的也是槽的 <code>concurrency</code>,所以有同样的现象;无 reactor 模式下它们也不起作用。</p>'),
     ('无 reactor 模式', '<p>aiohttp 下载处理器自己的连接器带 <code>limit</code> 和 <code>limit_per_host</code>,所以每域名限制由它保证。</p>')],
    steps,
    [ENV_Y + '。服务器端用线程服务器记录每个 Host 头(主机名)同时在处理的请求数的峰值;两个主机名用 127.0.0.1 和 localhost;为了看到槽的状态给 Downloader._download 打了补丁(只记录)',
     '没有验证:Scrapy 其它版本(2.18 及更早)是否有同样的现象,这是否已经在后续版本修复;启用 AutoThrottle 时的并发(下一批文章);真实网络(请求完成时间有抖动)下“一次放光”是否变轻;http11 下载处理器的连接池(maxPersistentPerHost)与此的关系;HTTP/2 处理器(见后面的文章)'],
    '并发限制')
